function greet(name: string) {
  return `Hello, ${name.toUpperCase()}`;
}

const maybe: string | undefined = process.env.USER_NAME;
// greet(maybe); // Error: undefined not assignable to string

if (maybe !== undefined) {
  greet(maybe); // narrowed to string
}

greet(maybe ?? 'Guest');

interface Profile {
  displayName: string;
  bio?: string; // string | undefined when present
}

function render(p: Profile) {
  const bio = p.bio?.trim() ?? '(no bio)';
  return `${p.displayName}: ${bio}`;
}

const fromApi: Profile = JSON.parse('{"displayName":"Ada"}');
render(fromApi); // bio undefined at runtime — optional chaining safe

async function getCachedUser(id: string): Promise<User | null> {
  const raw = await redis.get(`user:${id}`);
  if (raw === null) return null;

  const parsed: unknown = JSON.parse(raw);
  if (!isUser(parsed)) return null;
  return parsed;
}

async function greetUser(id: string) {
  const user = await getCachedUser(id);
  if (user === null) {
    return fetch(`/api/users/${id}`).then(r => r.json());
  }
  return user;
}

